def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(r.count(x) for r in grid))
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not pts:
        return [row[:] for row in grid]
    r0 = min(r for r, c in pts); r1 = max(r for r, c in pts)
    c0 = min(c for r, c in pts); c1 = max(c for r, c in pts)
    out = [row[:] for row in grid]
    # Fill any missing cells along the foreground bounding-box perimeter.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r in (r0, r1) or c in (c0, c1)) and out[r][c] == bg:
                out[r][c] = 2
    # Interpolate between foreground markers aligned in rows and columns.
    for r in range(h):
        for color in set(grid[r]) - {bg}:
            cols = [c for c, value in enumerate(grid[r]) if value == color]
            if len(cols) >= 2:
                for c in range(cols[0] + 1, cols[-1]):
                    if out[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        for color in {grid[r][c] for r in range(h)} - {bg}:
            rows = [r for r in range(h) if grid[r][c] == color]
            if len(rows) >= 2:
                for r in range(rows[0] + 1, rows[-1]):
                    if out[r][c] == bg:
                        out[r][c] = 2
    return out

