def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda color: sum(row.count(color) for row in grid))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = [row[:] for row in grid]

    # Complete the perimeter of the bounding box around all foreground cells.
    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r in (r0, r1) or c in (c0, c1)) and out[r][c] == bg:
                out[r][c] = 2

    # Complete gaps along any row or column with at least three aligned markers.
    for r in range(h):
        for color in set(grid[r]) - {bg}:
            cols = [c for c, value in enumerate(grid[r]) if value == color]
            if len(cols) >= 3:
                for c in range(cols[0] + 1, cols[-1]):
                    if out[r][c] == bg:
                        out[r][c] = 2
    for c in range(w):
        for color in {grid[r][c] for r in range(h)} - {bg}:
            rows = [r for r in range(h) if grid[r][c] == color]
            if len(rows) >= 3:
                for r in range(rows[0] + 1, rows[-1]):
                    if out[r][c] == bg:
                        out[r][c] = 2
    return out

